"""Persist explicitly inspected Administration artwork with content fingerprints."""
import argparse,hashlib,json,re
from pathlib import Path
import kb

def main(root,inspected):
 sid='src-000343';src=next(s for s in kb.sources(root) if s['source_id']==sid);base=root/src['set_path'];report=root/'tracking/reviews/t2s-administration-diagrams.json';old=json.loads(report.read_text(encoding='utf-8')) if report.exists() else {'records':[]};prior={r['diagram']:r for r in old['records']};manifest=json.loads((root/'work/t2s-admin-diagrams.json').read_text(encoding='utf-8'));items=[dict(x,diagram=x['figure_id']) for x in manifest['outputs']];items+=json.loads((root/'work/t2s-admin-modules.json').read_text(encoding='utf-8'))['records'];renders={x['diagram']:x for p in ['work/t2s-admin-render.json','work/t2s-admin-modules-render.json'] for x in json.loads((root/p).read_text(encoding='utf-8'))};records=[];indexrows=[];invp=root/'work/documents'/sid/'media-review-inventory.json';inv=json.loads(invp.read_text(encoding='utf-8'))
 for item in items:
  name=item['diagram'];rr=renders[name];assert rr['result']=='pass';page=root/item['path'];hashes={'mermaid_sha256':hashlib.sha256(page.with_suffix('.mmd').read_bytes()).hexdigest(),'original_sha256':hashlib.sha256((root/item['original']).read_bytes()).hexdigest(),'rendered_png_sha256':hashlib.sha256((root/rr['png']).read_bytes()).hexdigest()};assert hashes['mermaid_sha256']==item['mermaid_sha256'] and hashes['original_sha256']==item['original_sha256']
  if name not in inspected:
   assert name in prior and all(prior[name][k]==v for k,v in hashes.items()),'Explicit visual inspection required: '+name
  status='needs-review' if item['figure_id']=='fig-0001' else 'reviewed';issues=['issue-000039'] if status=='needs-review' else [];rec={**item,**hashes,'date':'2026-11-09','render_result':'pass','renderer':rr['renderer'],'renderer_version':rr['version'],'visual_review':'pass','review_status':status,'issue_ids':issues,'svg':rr['svg'],'png':rr['png'],'checks':['Original complete source preview and final Mermaid reconstruction directly viewed.','Every labelled node, actor, source module, connector endpoint, direction, condition and parallel bar compared.','Source decision and merge distinctions retained without inventing omitted failure or queue-restart connectors.','Local alternative labels and separate receipt/business-processing scenarios preserved.','Technical module diagrams retain all 34 and 104 respectively inventoried source edges; module detail views repeat boundary nodes explicitly.'],'limitations':['This review covers visible artwork. Hidden native embedded content remains separately scoped under issue-000028.','Mermaid changes layout, arrowhead styling and data-box underlining; textual descriptions preserve source meaning.']};records.append(rec);m,b=kb.metadata(page);m.update(review_status=status,issue_ids=issues,render_status='pass',visual_review='pass',visual_review_date='2026-11-09',renderer='Mermaid '+rr['version'],rendered_svg=rr['svg'],rendered_png=rr['png']);b=re.sub(r'## Rendering and visual review\n.*','## Rendering and visual review\n\nMermaid '+rr['version']+' with '+rr['renderer']+' parsed and rendered this view. On 2026-11-09, the original artwork and final reconstruction were directly compared for labels, modules, participants, every endpoint and direction, guards, forks/merges, alternative frames and the distinction between technical and business outcomes. **Visible-source fidelity: pass.** Source conflicts remain open where listed. Layout, arrowhead styling and underlined data-box typography differ; the original and explicit descriptions remain available. Hidden native content is a separate review scope.\n\n'+kb.link(page,root/rr['svg'],'Rendered SVG')+' · '+kb.link(page,root/rr['png'],'Rendered PNG')+' · '+kb.link(page,report,'Hash-bound review evidence')+'\n',b,flags=re.S);kb.put(page,kb.front(m)+b)
  if name==item['figure_id']:
   indexrows.append([name,kb.link(base/'diagrams/administration/index.md',page,m['title']),status])
   for media in inv['media']:
    for occ in media['occurrences']:
     if occ['figure_id']!=name:continue
     media.update(disposition='source-reconstruction',canonical_diagram=item['path'],review_status=status,visual_review='pass',complete_composite_review='complete-source-preview-compared; Word-page context separately available');occ['canonical_diagram']=item['path'];ep=root/occ['evidence_page'];em,eb=kb.metadata(ep);em.update(disposition='source-reconstruction',canonical_diagram=item['path'],review_status=status,render_status='pass',visual_review='pass');kb.put(ep,kb.front(em)+eb.strip()+'\n')
 legends=[]
 for media in inv['media']:
  for occ in media['occurrences']:
   num=int(occ['figure_id'][4:])
   if num not in (7,8,9,10):continue
   label={7:'Start Point',8:'End Point',9:'Lozenge (or diamond)',10:'Bar'}[num];media.update(disposition='retained-notation-legend',review_status='reviewed',visual_review='pass');ep=root/occ['evidence_page'];em,eb=kb.metadata(ep);em.update(disposition='retained-notation-legend',review_status='reviewed',visual_review='pass',limitations=['Substantive T11 notation key, not decorative artwork or an independent business diagram.']);eb=re.sub(r'\n<!-- ADMIN-LEGEND -->.*','',eb,flags=re.S);kb.put(ep,kb.front(em)+eb.strip()+'\n\n<!-- ADMIN-LEGEND -->\nOriginal '+label+' symbol directly viewed on 2026-11-09 and retained with the T11 description.\n');legends.append({'figure_id':occ['figure_id'],'label':label,'source_locator':occ['source_locator'],'original':media['original'],'original_sha256':media['original_sha256'],'disposition':'retained-notation-legend','visual_review':'pass','date':'2026-11-09'})
 kb.dump(invp,inv);kb.dump(report,{'source_id':sid,'source_sha256':src['sha256'],'date':'2026-11-09','records':records,'legend_records':legends,'substantive_figures':16,'reconstructed_views':len(records),'render_pass':len(records),'direct_visual_comparisons':len(records),'reviewed_figures':15,'needs_review_figures':1});idx=base/'diagrams/administration/index.md';kb.put(idx,kb.front({'template':False,'document_kind':'diagram-index','review_status':'needs-review','domain':'shared','source_ids':[sid],'source_editions':['March 2024'],'message_sets':['t2s-administration']})+'# T2S Administration source diagrams\n\nAll 20 figure occurrences are accounted for: 16 substantive source reconstructions, including three additional module detail views, and four retained T11 notation symbols. All 19 reconstructed views parsed/rendered with Mermaid12.3 and were directly compared with the originals. The role-hierarchy context remains needs-review under issue-000039. Native hidden-content scope is separate.\n\n'+kb.table(['Figure','Canonical reference','Status'],sorted(indexrows))+'\n'+kb.link(idx,report,'Hash-bound rendering and visual-review evidence')+'\n');print(json.dumps({'views':len(records),'figures':16,'legends':len(legends)}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);p.add_argument('--inspected',nargs='*',default=[]);a=p.parse_args();main(a.root.resolve(),a.inspected)
